"""matplotlib.patheffects — path effect stubs."""


class AbstractPathEffect:
    def __init__(self, offset=(0, 0)):
        self._offset = offset

    def draw_path(self, renderer, gc, tpath, affine, rgbFace=None):
        pass


class Normal(AbstractPathEffect):
    pass


class Stroke(AbstractPathEffect):
    def __init__(self, offset=(0, 0), **kwargs):
        super().__init__(offset)
        self._gc = kwargs


class SimplePatchShadow(AbstractPathEffect):
    def __init__(self, offset=(2, -2), shadow_rgbFace=None, alpha=None, rho=0.3, **kwargs):
        super().__init__(offset)
        self.shadow_rgbFace = shadow_rgbFace
        self.alpha = alpha
        self.rho = rho


class SimpleLineShadow(AbstractPathEffect):
    def __init__(self, offset=(2, -2), shadow_color='k', alpha=0.3, rho=0.3, **kwargs):
        super().__init__(offset)
        self.shadow_color = shadow_color
        self.alpha = alpha


class PathPatchEffect(AbstractPathEffect):
    def __init__(self, offset=(0, 0), **kwargs):
        super().__init__(offset)
        self._props = kwargs


class withStroke(Stroke):
    pass


class withSimplePatchShadow(SimplePatchShadow):
    pass


class TickedStroke(AbstractPathEffect):
    def __init__(self, offset=(0, 0), spacing=10.0, angle=45.0, length=1.414, **kwargs):
        super().__init__(offset)
        self.spacing = spacing
        self.angle = angle
        self.length = length


# ─── Added: missing public names from upstream patheffects.py ──────


class PathEffectRenderer:
    """A renderer wrapper that funnels every ``draw_path`` call through
    a list of :class:`AbstractPathEffect`s before delegating to the
    underlying renderer. Upstream uses it to implement the ``path_effects``
    artist property; the shim keeps the same surface so client code that
    walks the renderer chain can find it.
    """

    def __init__(self, path_effects, renderer):
        self._path_effects = list(path_effects)
        self._renderer = renderer

    def __getattr__(self, name):
        # Anything we don't explicitly override falls through to the
        # wrapped renderer.
        return getattr(self._renderer, name)

    def draw_path(self, gc, tpath, affine, rgbFace=None):
        for fx in self._path_effects:
            fx.draw_path(self._renderer, gc, tpath, affine, rgbFace)
        # Always also draw the original path.
        return self._renderer.draw_path(gc, tpath, affine, rgbFace)

    def copy_with_path_effect(self, path_effects):
        return PathEffectRenderer(path_effects, self._renderer)


class withTickedStroke(TickedStroke):
    """``TickedStroke`` variant that also draws the underlying stroke."""
    pass


# ─── PathEffectRenderer pass-throughs — funnel everything through the
#     underlying renderer so the wrapper is transparent for callers. ──


def _per_open_group(self, s, gid=None):
    return self._renderer.open_group(s, gid)


def _per_close_group(self, s):
    return self._renderer.close_group(s)


def _per_draw_markers(self, gc, marker_path, marker_trans, path, trans,
                       rgbFace=None):
    # Apply every path effect to each marker stamp, mirroring upstream.
    for fx in self._path_effects:
        try:
            fx.draw_path(self._renderer, gc, marker_path,
                          trans, rgbFace)
        except Exception:
            pass
    return self._renderer.draw_markers(gc, marker_path, marker_trans,
                                          path, trans, rgbFace)


def _per_draw_path_collection(self, gc, master_transform, paths, all_transforms,
                                offsets, offset_trans, facecolors, edgecolors,
                                linewidths, linestyles, antialiaseds, urls,
                                offset_position):
    return self._renderer.draw_path_collection(
        gc, master_transform, paths, all_transforms,
        offsets, offset_trans, facecolors, edgecolors,
        linewidths, linestyles, antialiaseds, urls,
        offset_position)


PathEffectRenderer.open_group           = _per_open_group
PathEffectRenderer.close_group          = _per_close_group
PathEffectRenderer.draw_markers         = _per_draw_markers
PathEffectRenderer.draw_path_collection = _per_draw_path_collection


# AbstractPathEffect.draw_path default — delegate to renderer when
# subclass doesn't override. Mirrors upstream's `Normal` semantics.
def _ape_draw_path(self, renderer, gc, tpath, affine, rgbFace=None):
    """Default: passthrough to the underlying renderer (no effect)."""
    return renderer.draw_path(gc, tpath, affine, rgbFace)


# Only attach the real default for Normal; the other classes already
# have explicit no-op draw_path stubs that subclasses are expected to
# override anyway.
Normal.draw_path = _ape_draw_path
